" placeholder=\"At least 8 characters\" minlength=\"8\" required />\n              </div>\n              <div class=\"field\">\n                <label>Confirm New Password</label>\n                <input type=\"password\" id=\"confirmPw\" placeholder=\"Re-enter new password\" minlength=\"8\" required />\n              </div>\n            </div>\n            <div class=\"hint\" id=\"pwHint\" style=\"color:var(--red);display:none;\">Passwords do not match.</div>\n            <div class=\"form-actions\">\n              <button type=\"submit\" class=\"btn btn-primary\">Update Password</button>\n              <span class=\"save-flash\" id=\"pwFlash\">✓ Password updated</span>\n            </div>\n          </form>\n        </div>\n      </div>\n\n      <!-- NOTIFICATIONS -->\n      <div class=\"card\">\n        <div class=\"card-head\">\n          <div class=\"ch-icon\">🔔</div>\n          <div><h2>Notifications</h2><p>Choose what updates you receive, by email and in-app</p></div>\n        </div>\n        <div class=\"card-body\" id=\"notifBody\"></div>\n      </div>\n\n      <!-- LOGOUT -->\n      <div class=\"card danger-card\">\n        <div class=\"card-head\">\n          <div class=\"ch-icon\">🚪</div>\n          <div><h2>Account</h2><p>Sign out of the teacher portal</p></div>\n        </div>\n        <div class=\"card-body\">\n          <div class=\"logout-row\">\n            <div class=\"lr-text\">\n              <div class=\"t\">Log out</div>\n              <div class=\"d\">You'll be signed out on this device and returned to the login page.</div>\n            </div>\n            <button class=\"btn btn-danger\" onclick=\"openLogout()\">Log Out</button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Logout modal -->\n  <div class=\"modal-overlay\" id=\"logoutModal\" onclick=\"if(event.target===this)closeLogout()\">\n    <div class=\"modal\">\n      <div class=\"m-icon\">🚪</div>\n      <h3>Log out?</h3>\n      <p>Are you sure you want to sign out of the SPS Teacher Portal?</p>\n      <div class=\"modal-actions\">\n        <button class=\"btn btn-ghost\" onclick=\"closeLogout()\">Cancel</button>\n        <button class=\"btn btn-danger\" onclick=\"doLogout()\">Log Out</button>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"toast\" id=\"toast\"></div>\n\n  <script>\n    const NOTIF = [\n      { id:'submissions', icon:'📝', bg:'#fdf3e3', title:'Assignment Submissions', desc:'When students submit work & grading deadlines', email:true, push:true },\n      { id:'classes',     icon:'📺', bg:'#e8f4fb', title:'Classes & Timetable', desc:'Live class reminders, substitutions & schedule changes', email:true, push:true },\n      { id:'attendance',  icon:'📅', bg:'#e8f4ec', title:'Attendance', desc:'Student attendance alerts & your own punch-in reminders', email:false, push:true },\n      { id:'exams',       icon:'📋', bg:'#f3eafd', title:'Exams & Invigilation', desc:'Datesheets, duty charts & marks-entry deadlines', email:true, push:true },\n      { id:'messages',    icon:'💬', bg:'#e9f1ee', title:'Messages', desc:'New messages, staff groups & class chats', email:false, push:true },\n      { id:'staff',       icon:'🏛️', bg:'#eaeef4', title:'Staff & Admin Notices', desc:'Principal announcements & circulars', email:true, push:true },\n      { id:'salary',      icon:'💰', bg:'#eef6f1', title:'Salary & Payslips', desc:'Payslip release & salary credit alerts', email:true, push:false },\n    ];\n\n    function renderNotif(){\n      const body = document.getElementById('notifBody');\n      body.innerHTML = NOTIF.map(n=>`\n        <div class=\"notif-row\">\n          <div class=\"notif-icon\" style=\"background:${n.bg}\">${n.icon}</div>\n          <div class=\"notif-info\">\n            <div class=\"ni-title\">${n.title}</div>\n            <div class=\"ni-desc\">${n.desc}</div>\n          </div>\n          <div class=\"notif-controls\">\n            <div class=\"toggle-wrap\"><span class=\"tw-label\">Email</span>\n              <label class=\"switch\"><input type=\"checkbox\" ${n.email?'checked':''} onchange=\"toggleNotif('${n.id}','email',this.checked)\"><span class=\"slider\"></span></label></div>\n            <div class=\"toggle-wrap\"><span class=\"tw-label\">In-App</span>\n              <label class=\"switch\"><input type=\"checkbox\" ${n.push?'checked':''} onchange=\"toggleNotif('${n.id}','push',this.checked)\"><span class=\"slider\"></span></label></div>\n          </div>\n        </div>`).join('');\n    }\n    function toggleNotif(id, channel, val){\n      const n = NOTIF.find(x=>x.id===id); n[channel]=val;\n      toast(`${n.title} ${channel==='email'?'email':'in-app'} alerts ${val?'on':'off'}`);\n    }\n\n    function flash(id){ const el=document.getElementById(id); el.classList.add('show'); setTimeout(()=>el.classList.remove('show'),2600); }\n    function saveEmail(e){ e.preventDefault(); flash('emailFlash'); toast('Verification link sent to new email'); e.target.reset(); }\n    function savePassword(e){\n      e.preventDefault();\n      const np=document.getElementById('newPw').value, cp=document.getElementById('confirmPw').value;\n      const hint=document.getElementById('pwHint');\n      if(np!==cp){ hint.style.display='block'; return; }\n      hint.style.display='none'; flash('pwFlash'); toast('Password updated successfully'); e.target.reset();\n    }\n\n    function openLogout(){ document.getElementById('logoutModal').classList.add('open'); }\n    function closeLogout(){ document.getElementById('logoutModal').classList.remove('open'); }\n    function doLogout(){ closeLogout(); toast('Logging out…'); setTimeout(()=>{ window.location.href='/'; }, 1100); }\n    document.addEventListener('keydown', e=>{ if(e.key==='Escape') closeLogout(); });\n\n    let toastT;\n    function toast(msg){ const t=document.getElementById('toast'); t.textContent=msg; t.classList.add('show'); clearTimeout(toastT); toastT=setTimeout(()=>t.classList.remove('show'),2400); }\n\n    renderNotif();\n  </script>\n\n<div class=\"sb-backdrop\" id=\"sbBackdrop\" onclick=\"closeSidebar()\"></div>\n<script>\nfunction openSidebar(){document.querySelector('.sidebar').classList.add('open');document.getElementById('sbBackdrop').classList.add('show');}\nfunction closeSidebar(){document.querySelector('.sidebar').classList.remove('open');document.getElementById('sbBackdrop').classList.remove('show');}\ndocument.querySelectorAll('.nav-item').forEach(el=>el.addEventListener('click',closeSidebar));\n</script>\n";
